package com.metaplatform.agent.events;
import jakarta.persistence.*; import lombok.*; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes; import java.time.Instant;
@Entity @Table(name="run_events") @Data @Builder @NoArgsConstructor @AllArgsConstructor public class RunEventEntity { @Id @Column(name="event_id",length=64) private String eventId; @Column(name="run_id",nullable=false,length=64) private String runId; @Column(name="task_id",length=64) private String taskId; @Column(name="sub_agent_id",length=64) private String subAgentId; @Column(name="parent_run_id",length=64) private String parentRunId; @Enumerated(EnumType.STRING) @Column(nullable=false,length=64) private RunEventType type; @Column(nullable=false) private Instant ts; @Column(name="trace_id",nullable=false,length=64) private String traceId; @Column(name="tenant_id",nullable=false,length=64) private String tenantId; @Column(name="envelope_id",length=64) private String envelopeId; @Lob @JdbcTypeCode(SqlTypes.JSON) @Column(nullable=false,columnDefinition="jsonb") private String payload; @Enumerated(EnumType.STRING) @Column(name="error_code",length=64) private RunErrorCode errorCode; @Column(nullable=false) private Long seq; @Column(name="created_at",nullable=false,updatable=false) private Instant createdAt; @PrePersist void prePersist(){ if(createdAt==null) createdAt=Instant.now(); if(ts==null) ts=createdAt; } }
